import{_ as a,o,c as r,a2 as n}from"./chunks/framework.A5mep7Fe.js";const d=JSON.parse('{"title":"🚀 03 · 预训练与 Scaling Law","description":"","frontmatter":{},"headers":[],"relativePath":"01-算法岗-AIGC与LLM/03-预训练与ScalingLaw.md","filePath":"01-算法岗-AIGC与LLM/03-预训练与ScalingLaw.md","lastUpdated":1786806808000}'),e={name:"01-算法岗-AIGC与LLM/03-预训练与ScalingLaw.md"};function l(s,t,i,g,c,h){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="🚀-03-·-预训练与-scaling-law" tabindex="-1">🚀 03 · 预训练与 Scaling Law <a class="header-anchor" href="#🚀-03-·-预训练与-scaling-law" aria-label="Permalink to &quot;🚀 03 · 预训练与 Scaling Law&quot;">​</a></h1><blockquote><p>理解「大模型是怎么被喂出来的」，以及「为什么越大越好（直到边际递减）」。</p></blockquote><hr><h2 id="一、预训练目标" tabindex="-1">一、预训练目标 <a class="header-anchor" href="#一、预训练目标" aria-label="Permalink to &quot;一、预训练目标&quot;">​</a></h2><p>预训练 = 在海量无标注文本上，用<strong>自监督</strong>任务学通用表示。两大范式：</p><table tabindex="0"><thead><tr><th>目标</th><th>定义</th><th>代表</th></tr></thead><tbody><tr><td><strong>CLM（因果语言建模）</strong></td><td>给定前文预测下一个 token，$P(x_t|x_{&lt;t})$</td><td>GPT 系、LLaMA</td></tr><tr><td><strong>MLM（掩码语言建模）</strong></td><td>随机遮盖部分 token 预测</td><td>BERT</td></tr></tbody></table><p>现代生成式 LLM 几乎都用 <strong>CLM</strong>（自回归），因为统一了「生成」能力。</p><hr><h2 id="二、算力-数据-参数-三角" tabindex="-1">二、算力-数据-参数 三角 <a class="header-anchor" href="#二、算力-数据-参数-三角" aria-label="Permalink to &quot;二、算力-数据-参数 三角&quot;">​</a></h2><p>预训练三大资源：</p><ul><li><strong>数据（Data）</strong>：质量 &gt; 数量。去重、过滤、配比（多语言/多领域）是关键。</li><li><strong>算力（Compute）</strong>：GPU 小时，决定能训多大。</li><li><strong>参数（Params）</strong>：模型容量。</li></ul><p>三者需<strong>均衡</strong>：数据不够，参数再大也过拟合/学不到；算力不够，数据用不完。</p><hr><h2 id="三、scaling-law-缩放定律-⭐" tabindex="-1">三、Scaling Law（缩放定律）⭐ <a class="header-anchor" href="#三、scaling-law-缩放定律-⭐" aria-label="Permalink to &quot;三、Scaling Law（缩放定律）⭐&quot;">​</a></h2><p><strong>核心结论</strong>（Kaplan 2020 / Chinchilla 2022）：模型<strong>损失</strong>随参数、数据、算力呈<strong>幂律下降</strong>：</p><p>$$L(N) \\propto N^{-\\alpha},\\quad L(D) \\propto D^{-\\beta},\\quad L(C) \\propto C^{-\\gamma}$$</p><p><strong>Chinchilla 修正</strong>：此前模型「参数过大、数据不足」。Chinchilla 指出<strong>最优配比约 20 tokens/参数</strong>。即 7B 模型应喂 ~140B tokens。</p><blockquote><p>本质判断：Scaling Law 是「经验规律」不是「物理定律」。它解释了过去 5 年的能力跃迁，但也暗示<strong>单纯堆量会边际递减</strong>——这正是推理时计算（test-time compute）与新范式被提出的原因。</p></blockquote><hr><h2 id="四、预训练关键工程" tabindex="-1">四、预训练关键工程 <a class="header-anchor" href="#四、预训练关键工程" aria-label="Permalink to &quot;四、预训练关键工程&quot;">​</a></h2><ol><li><strong>数据管线</strong>：爬取 → 清洗 → 去重（MinHash/SimHash）→ 配比 → tokenize。</li><li><strong>训练稳定性</strong>：学习率 warmup + cosine decay、混合精度（BF16）、loss 尖刺处理。</li><li><strong>长上下文续训</strong>：先用短上下文预训练，再「位置插值」续训拉长。</li><li><strong>并行策略</strong>：数据并行 / 张量并行 / 流水线并行 / ZeRO（见 <code>04-微调</code> 与分布式训练）。</li></ol><hr><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q1：为什么现在主流用 CLM 而不是 MLM？</strong></p><blockquote><p>CLM 天然支持生成，且自回归统一了「理解+生成」；MLM 的 [MASK] 在预训练-微调不一致，且不利于生成。</p></blockquote><p><strong>Q2：Scaling Law 会一直有效吗？</strong></p><blockquote><p>幂律在极大范围内成立，但边际收益递减。且「能力涌现」可能部分源于评测指标的非线性。当数据/算力逼近上限，需要新范式（推理时计算、更好的数据配方）。</p></blockquote><p><strong>Q3：数据质量和数量哪个更重要？</strong></p><blockquote><p>在大规模下，质量（去重+过滤+配比）往往比单纯堆量更关键。低质量数据会污染模型。</p></blockquote><hr><p>➡️ 下一步：<a href="./04-微调技术">04-微调技术</a></p>',31)])])}const u=a(e,[["render",l]]);export{d as __pageData,u as default};
